using System;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;

class Program
{
    static async Task<int> CountAsync(IEnumerable<int> values, CancellationToken token)
    {
        int count = 0;
        foreach (int value in values)
        {
            token.ThrowIfCancellationRequested();
            await Task.Delay(1, token);
            if (value > 0)
            {
                count += 1;
            }
        }
        return count;
    }

    static async Task Main()
    {
        Console.WriteLine(await CountAsync(new[] { 3, -1, 2 }, CancellationToken.None));
    }
}
